"""Transport identities from canonical tool calls, never generated by the model.

AttemptLedger still deduplicates semantic requests and blocks unknown effects.
No new database and no selection of commands, executors or technical decisions.
"""
from contextlib import contextmanager
from contextvars import ContextVar
import json

_INVOCATION=ContextVar('authority_durable_invocation',default=None)


@contextmanager
def invocation_scope(ident):
    token=_INVOCATION.set(ident)
    try:
        yield
    finally:
        _INVOCATION.reset(token)


def bind_execution(authority,arguments):
    """Require an actual started call in this task before assigning its key."""
    invocation=_INVOCATION.get()
    if not invocation:
        raise ValueError('Engine operation identity requires a canonical started tool invocation')
    with authority.store.db() as connection:
        row=connection.execute('SELECT mission,task,tool,arguments,state FROM tool_calls WHERE id=?',(invocation,)).fetchone()
    if not row or row['mission']!=authority.m or row['task']!=authority.t or row['state']!='started':
        raise ValueError('Operation identity does not belong to a started call of this mission/task')
    expected=json.loads(row['arguments'])
    if row['tool']=='authority_edit':
        import shlex
        from .distributed_authority import edit_program
        expected={**expected,'kind':'correct','command':'python3 -c '+shlex.quote(edit_program(expected['edits']))}
    elif row['tool']!='authority_work':
        raise ValueError('This tool invocation cannot dispatch an Authority execution')
    fields=('issue','kind','executor','command')
    if any(expected.get(field)!=arguments.get(field) for field in fields):
        raise ValueError('Execution differs from the canonical tool invocation; nothing dispatched')
    args={k:v for k,v in arguments.items() if k!='operation_id'}
    return {**args,'operation_id':'call:'+invocation},invocation
